"use client";

// Word-by-word analysis panel (FR-009).
//
// Renders the vendored QUL word segmentation for one verse: each token's
// Uthmani form, transliteration and gloss, aligned right-to-left in the
// Arabic's reading order.
//
// The panel is collapsible and loads the surah's word file only when opened.
// Word files are per-surah (the largest, al-Baqarah, is 273 KB), so eager
// loading on every reader page would be wasteful.
//
// Provenance: the data is generated by scripts/generate-word-data.js from the
// Quran.com API v4 (QUL word data) and vendored under public/word-data. The
// generator writes a sha256 manifest, and the dataset is never fetched from a
// third party at runtime.

import { useState } from "react";
import { ChevronDown, Languages } from "lucide-react";
import { useVerseWords, type WordToken } from "@/lib/quran/words";
import { getSource, sourceLanguageLabel } from "@/lib/quran/sources";
import { cn } from "@/lib/utils";

interface WordByWordProps {
  surah: number;
  ayah: number;
}

export function WordByWord({ surah, ayah }: WordByWordProps) {
  const [open, setOpen] = useState(false);

  return (
    <section
      aria-labelledby="word-by-word-heading"
      className="rounded-2xl border border-border/80 bg-card p-5"
    >
      <button
        type="button"
        onClick={() => setOpen((o) => !o)}
        aria-expanded={open}
        className="flex w-full items-center justify-between gap-3 text-left"
      >
        <div className="flex items-center gap-2">
          <Languages className="h-5 w-5 text-primary" aria-hidden />
          <h2 id="word-by-word-heading" className="font-display text-lg font-semibold">
            Word by word
          </h2>
        </div>
        <ChevronDown
          className={cn(
            "h-5 w-5 text-muted-foreground transition-transform",
            open && "rotate-180"
          )}
          aria-hidden
        />
      </button>

      <p className="mt-2 text-sm leading-relaxed text-muted-foreground">
        Each word of {surah}:{ayah} with its transliteration and English gloss.
        Loads when you expand this section.
      </p>

      {open && <WordTable surah={surah} ayah={ayah} />}
    </section>
  );
}

function WordTable({ surah, ayah }: { surah: number; ayah: number }) {
  const words = useVerseWords(surah, ayah);
  const source = getSource("qul-word-data");

  if (words === null) {
    return (
      <p role="status" className="mt-4 text-sm text-muted-foreground">
        Loading word data…
      </p>
    );
  }

  if (words.length === 0) {
    return (
      <p className="mt-4 text-sm text-muted-foreground">
        No word data is available for this verse.
      </p>
    );
  }

  return (
    <div className="mt-4 space-y-3">
      <ol className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
        {words.map((w) => (
          <WordCell key={w.position} word={w} />
        ))}
      </ol>

      {source && (
        <p className="text-[0.6875rem] leading-relaxed text-muted-foreground">
          Word data: {source.attribution} · {source.publisher} · License:{" "}
          {source.license} · Language: {sourceLanguageLabel(source.language)}.
          Glosses are a reading aid, not a translation of the verse.
        </p>
      )}
    </div>
  );
}

function WordCell({ word }: { word: WordToken }) {
  return (
    <li className="rounded-xl border border-border/70 bg-background/60 px-3 py-2">
      <p
        lang="ar"
        dir="rtl"
        className="arabic-text text-xl leading-relaxed text-foreground"
      >
        {word.arabic}
      </p>
      {word.transliteration && (
        <p lang="ar-Latn" className="mt-0.5 text-xs italic text-muted-foreground">
          {word.transliteration}
        </p>
      )}
      {word.translation && (
        <p lang="en" className="text-xs leading-snug text-foreground/80">
          {word.translation}
        </p>
      )}
    </li>
  );
}